INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2884719, 403378, 63360, '<td valign="top">Lovely symmetry.  The light cast on the walls is also nice.</td>', 'Lovely symmetry.  The light cast on the walls is also nice.', '2006-10-01 22:28:11.000000', NULL, 1),
(2884720, 392821, 35708, '<td valign="top">Very interesting composition and lighting... Not quite sure about the darker area on the bottom right and along the shoreline (the brighter blue) but it doesnt take away too much from the overall shot.</td>', 'Very interesting composition and lighting... Not quite sure about the darker area on the bottom right and along the shoreline (the brighter blue) but it doesnt take away too much from the overall shot.', '2006-10-01 22:28:38.000000', NULL, 1),
