(2884728, 395646, 35708, '<td valign="top">There is no subject that is prominent... so there is nothing to catch and hold attention.</td>', 'There is no subject that is prominent... so there is nothing to catch and hold attention.', '2006-10-01 22:30:05.000000', NULL, 1),
(2884729, 402275, 51538, '<td valign="top">Lively action you''ve caught there.</td>', 'Lively action you''ve caught there.', '2006-10-01 22:30:13.000000', NULL, 1),
