(2884732, 403689, 51538, '<td valign="top">Nice composition and focus.</td>', 'Nice composition and focus.', '2006-10-01 22:30:53.000000', NULL, 1),
(2884733, 404074, 10263, '<td valign="top">Those look like piggy-back plants. We used to have them wild here but I haven''t seen one for years. Nice nostalgic shot for me.</td>', 'Those look like piggy-back plants. We used to have them wild here but I haven''t seen one for years. Nice nostalgic shot for me.', '2006-10-01 22:31:03.000000', NULL, 1),
