(2884751, 404074, 51538, '<td valign="top">Nice counterpoint.  Simple but tells a good story. 7.</td>', 'Nice counterpoint.  Simple but tells a good story. 7.', '2006-10-01 22:35:42.000000', NULL, 1),
(2884753, 400910, 35708, '<td valign="top">Composition doesnt include anything that holds the attention...</td>', 'Composition doesnt include anything that holds the attention...', '2006-10-01 22:35:46.000000', NULL, 1),
