(2884755, 398052, 51538, '<td valign="top">Nice colours and angle.</td>', 'Nice colours and angle.', '2006-10-01 22:36:20.000000', NULL, 1),
(2884757, 396873, 3102, '<td valign="top">I like the pose and everything, but her face just seems to be a bit *too* high key for me compared to the rest of the shot.  With the rest of the shot being predominently dark, it makes the face seem blown out.  Still a 6, though :)</td>', 'I like the pose and everything, but her face just seems to be a bit *too* high key for me compared to the rest of the shot.  With the rest of the shot being predominently dark, it makes the face seem blown out.  Still a 6, though :)', '2006-10-01 22:37:05.000000', NULL, 1),
(2884758, 391988, 10263, '<td valign="top">Oh wow.. drop-dead gorgeous. Other than the horizon being a tiny bit off everything about it is perfect. 9</td>', 'Oh wow.. drop-dead gorgeous. Other than the horizon being a tiny bit off everything about it is perfect. 9', '2006-10-01 22:37:07.000000', NULL, 1),
(2884760, 401004, 51538, '<td valign="top">Maine?  Whatever, the rocks have a pleasing cleavage or bedding plane orientation (speaking as a geologist).</td>', 'Maine?  Whatever, the rocks have a pleasing cleavage or bedding plane orientation (speaking as a geologist).', '2006-10-01 22:37:16.000000', NULL, 1),
