(2884780, 398307, 35708, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-10-01 22:40:31.000000', NULL, 1),
(2884782, 403783, 35708, '<td valign="top">Some shadows on the subject would help this a lot.</td>', 'Some shadows on the subject would help this a lot.', '2006-10-01 22:41:09.000000', NULL, 1),
