(2887986, 401901, 62095, '<td valign="top">This is an interesting semi-abstract shot. Maintained my attention for longer than this type of photo normally does, got to be worth something.</td>', 'This is an interesting semi-abstract shot. Maintained my attention for longer than this type of photo normally does, got to be worth something.', '2006-10-02 17:05:02.000000', NULL, 1),
(2887989, 389939, 42100, '<td valign="top">Quite an unusual, but a very good composition.  Great lighting and exposure on this fascinating photo.</td>', 'Quite an unusual, but a very good composition.  Great lighting and exposure on this fascinating photo.', '2006-10-02 17:05:30.000000', NULL, 1),
(2887991, 402436, 62095, '<td valign="top">The colours (or lack of) work well here. The grime and oily nature seems well reproduced.</td>', 'The colours (or lack of) work well here. The grime and oily nature seems well reproduced.', '2006-10-02 17:05:40.000000', NULL, 1),
