(2890176, 398401, 61318, '<td valign="top">very good decision going with the b+w here</td>', 'very good decision going with the b+w here', '2006-10-03 05:39:20.000000', NULL, 1),
(2890177, 403614, 33352, '<td valign="top">A lot of voters will probably not understand this photo, I saw a photo the same as this different subject, win the world wide ballantine photography competition, congratulatons for entering it....8</td>', 'A lot of voters will probably not understand this photo, I saw a photo the same as this different subject, win the world wide ballantine photography competition, congratulatons for entering it....8', '2006-10-03 05:39:20.000000', NULL, 1),
