(2891007, 400248, 51538, '<td valign="top">Very nice composition.  The varied light fall works well. 9.</td>', 'Very nice composition.  The varied light fall works well. 9.', '2006-10-03 11:32:52.000000', NULL, 1),
(2891009, 403236, 33361, '<td valign="top">unbelievably fabulous! 10+++</td>', 'unbelievably fabulous! 10+++', '2006-10-03 11:32:58.000000', NULL, 1),
