INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2902917, 394649, 64175, '<td valign="top">Nice shot and angle.  The lighting is just a bit much above his left temple.</td>', 'Nice shot and angle.  The lighting is just a bit much above his left temple.', '2006-10-06 12:38:08.000000', NULL, 1),
(2902918, 399708, 64175, '<td valign="top">Looks like one from the leading lines challenge.  Nice shot.</td>', 'Looks like one from the leading lines challenge.  Nice shot.', '2006-10-06 12:38:35.000000', NULL, 1),
(2902919, 397954, 64175, '<td valign="top">Simply put...beautiful.</td>', 'Simply put...beautiful.', '2006-10-06 12:39:02.000000', NULL, 1),
(2902922, 404049, 64175, '<td valign="top">While the shot and bocca is nice, the subject itself is just not overly interesting to me.</td>', 'While the shot and bocca is nice, the subject itself is just not overly interesting to me.', '2006-10-06 12:39:52.000000', NULL, 1),
(2902926, 395586, 64175, '<td valign="top">Nice shot. One of those cherishable moments.  B/W nice touch. I think I would have prefered it without the white fading in the corners (can''t think of the technical term for that, sorry).</td>', 'Nice shot. One of those cherishable moments.  B/W nice touch. I think I would have prefered it without the white fading in the corners (can''t think of the technical term for that, sorry).', '2006-10-06 12:41:25.000000', NULL, 1),
(2902928, 403188, 64175, '<td valign="top">Too much of the image is out of focus.</td>', 'Too much of the image is out of focus.', '2006-10-06 12:42:12.000000', NULL, 1),
(2902929, 396113, 42100, '<td valign="top">I can''t remember ever having seen the bay bridge photographed from this angle.  I like how the flow goes back under the bridge and over towards Oakland, too bad the island(the name has left me right now) breaks that flow a little.  <br/> <br/>The embarrassing part...I looked at this for a little while trying to figure out from which side of the bay you took the a photo of the Golden Gate Bridge.  Not only are there too many towers, but you even say Bay Bridge in the title. <br/> <br/>Oh, in all that babble I failed to say...great photo!</td>', 'I can''t remember ever having seen the bay bridge photographed from this angle.  I like how the flow goes back under the bridge and over towards Oakland, too bad the island(the name has left me right now) breaks that flow a little.   The embarrassing part...I looked at this for a little while trying to figure out from which side of the bay you took the a photo of the Golden Gate Bridge.  Not only are there too many towers, but you even say Bay Bridge in the title.  Oh, in all that babble I failed to say...great photo!', '2006-10-06 12:42:19.000000', NULL, 1),
(2902937, 400405, 64175, '<td valign="top">Nice crisp clear shot. Would show better if the faces of the ducklings were just a bit more pronounced (raised).</td>', 'Nice crisp clear shot. Would show better if the faces of the ducklings were just a bit more pronounced (raised).', '2006-10-06 12:45:34.000000', NULL, 1),
