(2908658, 402564, 22734, '<td valign="top">Congratulations on your top 20 finish with autumnal beauty.</td>', 'Congratulations on your top 20 finish with autumnal beauty.', '2006-10-08 18:20:01.000000', NULL, 0),
(2908660, 403299, 22734, '<td valign="top">Simply amazing. A great visual treat. Congratulations on your top 20 finish.</td>', 'Simply amazing. A great visual treat. Congratulations on your top 20 finish.', '2006-10-08 18:20:36.000000', NULL, 0),
(2908664, 401012, 22734, '<td valign="top">An image hat deserves an even higher placing in this challenge. Great breath and lovely vantage point. Congratulations on your top 20 finish.</td>', 'An image hat deserves an even higher placing in this challenge. Great breath and lovely vantage point. Congratulations on your top 20 finish.', '2006-10-08 18:21:55.000000', NULL, 0),
